"""Hand-authored stage C2 records for the 2-prefix leaves. Run after reviewing source claims."""
import copy
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
ism = json.loads((ROOT / "public/ism.json").read_text(encoding="utf-8"))
enrich = json.loads((ROOT / "public/cube-enrichments.json").read_text(encoding="utf-8"))["nodes"]
b = {n["code"]: n for n in json.loads((HERE / "sol-tree-B.json").read_text(encoding="utf-8"))["nodes"]}
pilot = {n["code"]: n for n in json.loads((HERE.parent / "sol-categories.json").read_text(encoding="utf-8"))["categories"]}
c1 = {n["code"]: n for n in json.loads((HERE / "sol-tree-C1.json").read_text(encoding="utf-8"))["nodes"]}
sources = {}

for code, node in b.items():
    for side, tag in (("pro_sources", "P"), ("con_sources", "C")):
        if node[side]:
            sources[f"B:{code}:{tag}"] = copy.deepcopy(node[side][0])
for code in ("2-3-1-3", "2-3-2-4", "2-4-1-3", "2-4-1-4"):
    profile = pilot[code]["stance_profile"]["primary_evidence"]
    for side, tag in (("pro", "P"), ("con", "C")):
        item = profile[side]
        sources[f"P:{code}:{tag}"] = dict(author=item["author"], work=item["work"], version=item["edition_translation"], locator=item["locator"], url=item["url"], read_scope=item["review_scope"], supports=item["supports"], limits=item["limits"], relation="editorial_partial_comparison")
for code in ("1-2-3-4", "1-3-3-1", "1-2-2-4", "1-2-1-2", "1-4-2-1"):
    sources[f"C1:{code}:P"] = copy.deepcopy(c1[code]["pro_sources"][0])
    if c1[code]["con_sources"]:
        sources[f"C1:{code}:C"] = copy.deepcopy(c1[code]["con_sources"][0])

def source(key, author, work, version, locator, url, supports, limits):
    sources[key] = dict(author=author, work=work, version=version, locator=locator, url=url,
                        read_scope=locator, supports=supports, limits=limits,
                        relation="editorial_partial_comparison")

