for record in records:
    record["con"] = counter_overrides.get(record["code"], record["con"])
    record["pro"] = positive_overrides.get(record["code"], record["pro"])
    record.update(record_overrides.get(record["code"], {}))

problem_overrides = {
    "2-3-4-4": "在原子造物与神的自由创造之间，绝对时空怎样给出共同可测的秩序？",
    "2-4-4-3": "现实与语言无法完全重合时，怎样借大名称让不同知识暂时共同谈论，又不封闭本体？",
    "2-4-3-4": "多种描述都能对应经验而无一获本体特权时，科学共同体怎样选择可用版本？",
    "2-4-3-3": "私人感知与公共逻辑地图分离时，词语分类与行为线索怎样让理解可比较？",
    "2-2-4-4": "彼此经验与有无之辨无法由一个总语言统合时，怎样让具体事物不被固定名相吞没？",
    "2-3-1-4": "多种存在与认识层次怎样在一个神圣一元结构中取得位置？",
    "2-4-1-1": "被动实验所得的自然现象与上帝的法则怎样相接，以承受安排？",
    "2-3-3-4": "生命意志不断制造痛苦时，是否有不再由欲求驱动的出路？",
    "2-2-4-1": "执著与苦相连时，怎样松开概念化的‘我’与‘物’以求超脱？",
    "2-4-2-4": "多种生物变化可能分化也可能失败时，科学解释怎样以具体生存而非抽象上升为尺度？",
    "2-4-4-1": "孤立词义无法独自给出知识时，怎样用整套理论检验来指导可修正的实践？",
}
for record in records:
    if record["code"] in problem_overrides:
        record["problem"] = problem_overrides[record["code"]]

def build():
    expected = {f"2-{i}-{j}-{k}" for i in range(1, 5) for j in range(1, 5) for k in range(1, 5)}
    codes = [r["code"] for r in records]
    assert len(codes) == 64 and len(set(codes)) == 64 and set(codes) == expected, (len(codes), sorted(expected - set(codes)))
    dimensions = ("场域论", "本体论", "认识论", "目的论")
    out = []
    for r in records:
        code = r["code"]
        parent = code.rsplit("-", 1)[0]
        assert parent in b and len(ism[code]["axis_list"]) == 4
        transcripts = enrich[code].get("transcripts", [])
        pro = [copy.deepcopy(sources[r["pro"]])] if r["pro"] else []
        con = [copy.deepcopy(sources[r["con"]])] if r["con"] else []
        for s in con:
            s["relation"] = "editorial_counterargument_or_limit"
        status = ("partial" if pro and con else "positive_and_counter_gap" if not pro and not con
                  else "positive_gap" if not pro else "counter_gap")
        out.append({
            "code": code, "name": ism[code]["ch_name"], "depth": 4, "parent": parent,
            "course_evidence": {
                "lecture_url": transcripts[0]["url"] if transcripts else None,
                "original_video_url": None,
                "axis_locator": [f"public/ism.json[{code}].axis_list", "固定课程讲稿由 cube-enrichments.transcripts 指向；本轮未逐段核读，不主张讲稿页行已复核"],
                "course_axes": [dict(dimension=d, status="course_defined", course_wording=w) for d, w in zip(dimensions, ism[code]["axis_list"])],
                "scope": "课程轴保留原库措辞；原典只支持各节点标明的局部命题，不能由原典补全课程四格"},
            "stance_profile": {
                "position_title": f"定位：{code}｜{ism[code]['ch_name']}",
                "portrait": r["portrait"], "core_commitments": [r["axes"][1], r["axes"][3]],
                "problem_conflict": r["problem"],
                "axes_plain": [dict(dimension=d, status="course_defined", text=t) for d, t in zip(dimensions, r["axes"])],
                "synthetic_example": {"synthetic": True, "text": r["example"]},
                "strong_opponent": {"argument": r["opponent"], "relation": "依据反方原典作编者重构，并非作者间直接论战", "fairness": "反方命题与原典支持范围分开记录", "possible_response": r["reply"], "fair_reply": r["reply"]},
                "internal_tension": r["tension"], "dialectical_assessment": r["assessment"],
                "self_questions": [r["question"]], "neighbor_distinction": r["redirect"],
                "decision_rule": {"candidate_if": r["candidate"], "redirect_or_exclude_if": r["redirect"]}},
            "pro_sources": pro, "con_sources": con,
            "evidence_status": {"course": "原库四维定义已读；讲稿地址复用 manifest，未逐段核读", "audio_verified": False,
                                "primary": status, "note": "原典仅支持列出的局部命题；" + (r["note"] or "目的格证据范围见各来源限制")}
        })
    out.sort(key=lambda n: tuple(map(int, n["code"].split("-"))))
    payload = {"schema_version": "1.0", "scope": "阶段C2：2字头64个四级格位；与A/B/C1独立；正反原典仅作局部对照", "nodes": out}
    (HERE / "sol-tree-C2.json").write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("wrote", len(out), "nodes", "positive gaps", sum(not n["pro_sources"] for n in out), "counter gaps", sum(not n["con_sources"] for n in out))

if __name__ == "__main__":
    build()
